use forge_domain :: SyncProgress ; use forge_api :: WorkspaceId ; use pretty_assertions :: assert_eq ; use super :: * ; impl SyncProgressDisplay for SyncProgress { fn message (& self) -> Option < String > { match self { Self :: Starting => Some ("Initializing sync" . to_string ()) , Self :: WorkspaceCreated { workspace_id } => { Some (format ! ("Created workspace: {}" , workspace_id)) } Self :: DiscoveringFiles { path : _ , workspace_id } => { Some (format ! ("Analyzing workspace: {workspace_id}")) } Self :: FilesDiscovered { count : _ } => None , Self :: ComparingFiles { .. } => None , Self :: DiffComputed { added , deleted , modified } => { let total = added + deleted + modified ; if total == 0 { Some ("Index is up to date" . to_string ()) } else { let mut parts = Vec :: new () ; if * added > 0 { parts . push (format ! ("{} added" , added)) ; } if * modified > 0 { parts . push (format ! ("{} modified" , modified)) ; } if * deleted > 0 { parts . push (format ! ("{} removed" , deleted)) ; } Some (format ! ("Change scan completed [{}]" , parts . join (", "))) } } Self :: Syncing { current , total } => { let width = total . to_string () . len () ; let file_word = pluralize (* total) ; Some (format ! ("Syncing {:>width$}/{} {}" , current , total , file_word)) } Self :: Completed { uploaded_files , total_files , failed_files } => { if * uploaded_files == 0 && * failed_files == 0 { Some (format ! ("Index up to date [{} {}]" , total_files , pluralize (* total_files))) } else if * failed_files == 0 { Some (format ! ("Sync completed successfully [{uploaded_files}/{total_files} {} updated]" , pluralize (* uploaded_files) ,)) } else { Some (format ! ("Sync completed with errors [{uploaded_files}/{total_files} {} updated, {failed_files} failed]" , pluralize (* uploaded_files) ,)) } } } } }